import{_ as n,o as a,c as e,ag as p}from"./chunks/framework.DUTPmUpA.js";const d=JSON.parse('{"title":"Пользовательская система маны","description":"","frontmatter":{"title":"Пользовательская система маны","author":"Noya","steamId":"76561198046984233","date":"01.12.2014"},"headers":[],"relativePath":"scripting/custom-mana-system.md","filePath":"scripting/custom-mana-system.md"}'),l={name:"scripting/custom-mana-system.md"};function i(r,s,t,c,u,o){return a(),e("div",null,[...s[0]||(s[0]=[p(`<p>тельская система маны</p><p>Это руководство по созданию простой пользовательской системы маны. Предполагается работающий аддон barebone-системы.</p><p>В этом примере мы создадим классическую систему <em>Rage</em>, что означает:</p><ol><li>Нет нормальной регенерации маны, стартовая мана 0.</li><li>Получите ману после атаки, которая зависит от уровня.</li><li>Получите ману после атаки, которая зависит от уровня.</li><li>Получите ману при произнесении определенного заклинания.</li><li>Уменьшайте ману с течением времени, масштабируясь с уровнем.</li></ol><h2 id="нет-нормальнои-регенерации-маны-стартовая-мана-с-0" tabindex="-1">Нет нормальной регенерации маны, стартовая мана с 0. <a class="header-anchor" href="#нет-нормальнои-регенерации-маны-стартовая-мана-с-0" aria-label="Permalink to &quot;Нет нормальной регенерации маны, стартовая мана с 0.&quot;">​</a></h2><p>Более простой подход — свести на нет интеллект вашего героя. Для этого вам нужно установить следующее в определении вашего героя:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//KV code inside npc_heroes_custom.txt</span></span>
<span class="line"><span>&quot;AttributeBaseIntelligence&quot; &quot;0&quot;</span><span> // Base intelligence</span></span>
<span class="line"><span>&quot;AttributeIntelligenceGain&quot; &quot;0&quot;</span><span> // Intelligence bonus per level.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;StatusMana&quot;	&quot;50&quot;</span><span>    // Initial Max Mana</span></span>
<span class="line"><span>&quot;StatsManaRegen&quot;	&quot;0&quot;</span><span>	// Base Mana Regen (KV doesn&#39;t like negative numbers here)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Если вам нужно сохранить свой показатель Интеллекта, но у вас по-прежнему 0 естественной регенерации маны, вам нужно будет применить модификаторы для каждого очка Интеллекта с отрицательной регенерацией маны, чтобы компенсировать это.</p><p>Я не буду подробно описывать этот процесс в этом руководстве, но вы можете ознакомиться с руководством <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Scripting/Using_Bitfields_To_Adjust_Stat_Value_Bonuses" target="_blank" rel="noreferrer">on the wiki</a>.</p><p>Чтобы ваша мана начиналась с 0, мы начнем с создания пассивной скрытой способности, которая станет основой нашей системы ярости:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//KV code inside npc_abilities_custom.txt</span></span>
<span class="line"><span>&quot;barbarian_rage&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityTextureName&quot;	&quot;barbarian_rage&quot;</span></span>
<span class="line"><span>    &quot;MaxLevel&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot;	&quot;DOTA_ABILITY_BEHAVIOR_PASSIVE | DOTA_ABILITY_BEHAVIOR_HIDDEN&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;rage_modifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Passive&quot;	&quot;1&quot;</span><span>	//Auto apply this modifier when the spell is learned</span></span>
<span class="line"><span>            &quot;IsBuff&quot;	&quot;1&quot;</span><span>	//Display as a green modifier</span></span>
<span class="line"><span>            &quot;IsHidden&quot;	&quot;0&quot;</span><span>	//Show in the UI</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;OnCreated&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;RunScript&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;ScriptFile&quot;	&quot;barbarian.lua&quot;</span></span>
<span class="line"><span>                    &quot;Function&quot;	&quot;ZeroManaOnSpawn&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><p>Для этого требуется скрипт <code>barbarian.lua</code> внутри папки <em>your_addon/scripts/vscripts</em>. Скрипт очень простой:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span> -- lua code inside barbarian.lua</span></span>
<span class="line"><span>    function ZeroManaOnSpawn( event )</span></span>
<span class="line"><span>        local hero = event.caster</span></span>
<span class="line"><span>        Timers:CreateTimer(.01, function()</span></span>
<span class="line"><span>        -- Set Mana to 0 on created</span></span>
<span class="line"><span>        hero:SetMana(0)</span></span>
<span class="line"><span>    end)</span></span>
<span class="line"><span> end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Нам нужно немного подождать, чтобы герой появился правильно, иначе это может потерпеть неудачу. Обратите внимание на использование <a href="https://github.com/bmddota/barebones/blob/source2/game/dota_addons/barebones/scripts/vscripts/timers.lua" target="_blank" rel="noreferrer">BMD&#39;s Timers</a>.</p><h3 id="прежде-чем-мы-продолжим" tabindex="-1">Прежде чем мы продолжим: <a class="header-anchor" href="#прежде-чем-мы-продолжим" aria-label="Permalink to &quot;Прежде чем мы продолжим:&quot;">​</a></h3><p>Сейчас наше заклинание даже не доступно герою, и мы хотим, чтобы оно было изучено при появлении. Для этого нам нужно добавить следующее в наш прослушиватель <code>OnHeroInGame</code>* (*функция npc_spawned, см. <a href="https://github.com/bmddota/barebones/blob/source2/game/dota_addons/barebones/scripts/vscripts/barebones.lua#L443" target="_blank" rel="noreferrer">barebones Event Hooks</a> )</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>-- lua code inside OnHeroInGame(hero)</span></span>
<span class="line"><span>local heroName = hero:GetUnitName()</span></span>
<span class="line"><span>if heroName == &quot;npc_dota_hero_beastmaster&quot; then</span></span>
<span class="line"><span>    -- Add the spell</span></span>
<span class="line"><span>    hero:AddAbility(&quot;barbarian_rage&quot;)</span></span>
<span class="line"><span>    -- Level it up</span></span>
<span class="line"><span>    hero:FindAbilityByName(&quot;barbarian_rage&quot;):SetLevel(1)</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Если это не совсем необходимо, но вам нужно будет как-то отфильтровать желаемого героя. В нашем примере мы будем использовать Beastmaster.</p><h2 id="получает-ману-после-атаки-масштабируется-с-уровнем" tabindex="-1">Получает ману после атаки, масштабируется с уровнем <a class="header-anchor" href="#получает-ману-после-атаки-масштабируется-с-уровнем" aria-label="Permalink to &quot;Получает ману после атаки, масштабируется с уровнем&quot;">​</a></h2><p>Наш блок rage_modifier получает еще одно событие-модификатор:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;OnAttackLanded&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;RunScript&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ScriptFile&quot;	&quot;barbarian.lua&quot;</span></span>
<span class="line"><span>        &quot;Function&quot;	&quot;ManaOnAttack&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Я буду использовать для этого базовую формулу, которая дает базовую ману за атаку, но также немного увеличивается с уровнем. Имейте в виду, что эта функция используется для системы уровня героя 200, поэтому, если у вас есть что-то другое или большие затраты маны, вам нужно настроить ее по своему вкусу.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>-- lua code inside barbarian.lua</span></span>
<span class="line"><span>function ManaOnAttack( event )</span></span>
<span class="line"><span>    local hero = event.caster</span></span>
<span class="line"><span>    local level = hero:GetLevel()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    hero:GiveMana(0.01 * level + 3)</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="получите-ману-после-атаки-которая-зависит-от-уровня" tabindex="-1">Получите ману после атаки, которая зависит от уровня. <a class="header-anchor" href="#получите-ману-после-атаки-которая-зависит-от-уровня" aria-label="Permalink to &quot;Получите ману после атаки, которая зависит от уровня.&quot;">​</a></h2><p>Наш блок модификаторов получает еще одно событие-модификатор:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;OnAttacked&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   &quot;RunScript&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ScriptFile&quot;	&quot;barbarian.lua&quot;</span></span>
<span class="line"><span>        &quot;Function&quot;	&quot;ManaOnAttacked&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Как и раньше, можно использовать другую формулу: мы будем давать немного меньше маны при атаке.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function ManaOnAttacked( event )</span></span>
<span class="line"><span>   local hero = event.caster</span></span>
<span class="line"><span>   local level = hero:GetLevel()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   hero:GiveMana(0.01 * level + 0.4)</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="получите-ману-при-использовании-определенного-заклинания" tabindex="-1">Получите ману при использовании определенного заклинания. <a class="header-anchor" href="#получите-ману-при-использовании-определенного-заклинания" aria-label="Permalink to &quot;Получите ману при использовании определенного заклинания.&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;OnSpellStart&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;RunScript&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ScriptFile&quot;	&quot;barbarian.lua&quot;</span></span>
<span class="line"><span>        &quot;Function&quot;	&quot;leap&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Тогда в вашем скрипте заклинания lua нам нужно где-то это указать:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>local manaGain = event.ability:GetSpecialValueFor(&quot;mana_gain&quot;)</span></span>
<span class="line"><span>event.caster:GiveMana(manaGain)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Это возьмет ваш «mana_gain» из «AbilityValues», в моем примере с прыжком это будет:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;AbilityValues&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;mana_gain&quot; &quot;8 16 25 35 47 60 72 85&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="уменьшение-маны-с-течением-времени-масштабируемое-с-уровнем" tabindex="-1">Уменьшение маны с течением времени, масштабируемое с уровнем <a class="header-anchor" href="#уменьшение-маны-с-течением-времени-масштабируемое-с-уровнем" aria-label="Permalink to &quot;Уменьшение маны с течением времени, масштабируемое с уровнем&quot;">​</a></h2><p>Вначале мы установили для нашего StatsManaRegen значение 0. Это сделано для правильного динамического управления регенерацией маны в нашем основном файле lua.</p><p>Базовую регенерацию маны необходимо будет обновлять, когда герой порождает <code>OnHeroInGame</code>, а затем каждый раз, когда он повышает уровень <code>OnPlayerLevelUp</code>, если мы хотим, чтобы он масштабировался.</p><p>Для этого мы создаем локальную функцию где-то внутри нашего основного lua-файла дополнения и вызываем ее всякий раз, когда нам нужно (хотя бы один раз <code>OnHeroInGame</code>):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function AdjustWarriorClassMana( hero )</span></span>
<span class="line"><span>    Timers:CreateTimer(0.1,function()</span></span>
<span class="line"><span>        local heroLevel = hero:GetLevel()</span></span>
<span class="line"><span>        -- Adjust the new mana regen</span></span>
<span class="line"><span>        hero:SetBaseManaRegen( -(0.01 * heroLevel) - 0.25)</span></span>
<span class="line"><span>    end)</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>При этом мана нашего героя будет уменьшаться со временем примерно на 0,3 и немного быстрее на более высоких уровнях.</p><p>Проверьте исходные полные файлы сценариев в TBR Github.</p><ul><li><p><a href="https://github.com/Aleteh/TBR3/blob/master/scripts/vscripts/tbr.lua" target="_blank" rel="noreferrer">main lua scripts</a></p></li><li><p><a href="https://github.com/Aleteh/TBR3/blob/master/scripts/vscripts/abilities/barbarian.lua" target="_blank" rel="noreferrer">barbarian lua scripts</a></p></li><li><p><a href="https://github.com/Aleteh/TBR3/blob/master/scripts/npc/npc_heroes_custom.txt" target="_blank" rel="noreferrer">heroes_custom file</a></p></li><li><p><a href="https://github.com/Aleteh/TBR3/blob/master/scripts/npc/npc_abilities_custom.txt" target="_blank" rel="noreferrer">abilities file</a></p></li></ul>`,42)])])}const m=n(l,[["render",i]]);export{d as __pageData,m as default};
